INSERT INTO "app_settings" ("setting_key", "setting_value", "updated_at") VALUES ('site_config', '{"default_theme": "light", "default_accent": "blue", "auth_settings": {"password_login_enabled": true, "wechat_login_enabled": false, "quick_select_enabled": true, "wechat_runtime_test_enabled": true, "wechat": {"app_id": "", "app_secret": "", "redirect_uri": "http://127.0.0.1:5001/api/h5/wechat/callback", "scope": "snsapi_userinfo", "auto_register_enabled": false, "default_role": "investor", "default_tenant_slug": "", "default_advisor_name": ""}}, "voice_transcription": {"engine": "local", "post_process_mode": "rule_based", "domain_glossary_enabled": true}, "voice_embedding": {"engine": "local"}, "knowledge_ingestion": {"user_preview_enabled": false}, "hermes_settings": {"prompt_scope_guard_enabled": true, "investor_access_enabled": false, "dav_access_enabled": true, "internet_answer_enabled": true, "thinking_process_enabled": true, "answer_save_to_knowledge_enabled": true, "default_response_style": "structured", "chart_types_enabled": ["kline_chart", "line_chart", "distribution_chart", "compare_chart"], "route_priority": ["session_load", "memory_read", "fast_path", "scope_guard", "intent_router", "knowledge.search", "platform_tools", "attachment.context", "web.search", "answer_synthesis"], "intent_tree": [{"id": "knowledge_lookup", "label": "知识问答", "group": "knowledge_qa", "enabled": true, "display_mode": "text", "allow_knowledge": true, "allow_web": true, "allow_files": true, "allow_chart": false}, {"id": "watchlist_fundamental", "label": "个股 / 自选股", "group": "market_data_query", "enabled": true, "display_mode": "structured", "allow_knowledge": true, "allow_web": true, "allow_files": true, "allow_chart": true}, {"id": "smart_indicator_explain", "label": "指标 / 图表", "group": "chart_visualization", "enabled": true, "display_mode": "structured", "allow_knowledge": true, "allow_web": true, "allow_files": false, "allow_chart": true}, {"id": "evidence_chain_analysis", "label": "复盘 / 证据链", "group": "review_assistant", "enabled": true, "display_mode": "structured", "allow_knowledge": true, "allow_web": true, "allow_files": true, "allow_chart": false}, {"id": "dashboard_interpretation", "label": "Dashboard 解读", "group": "dashboard_indicator_assistant", "enabled": true, "display_mode": "structured", "allow_knowledge": true, "allow_web": false, "allow_files": false, "allow_chart": true}, {"id": "multi_tool_research", "label": "多工具研究", "group": "content_generation", "enabled": true, "display_mode": "structured", "allow_knowledge": true, "allow_web": true, "allow_files": true, "allow_chart": true}, {"id": "product_help", "label": "产品帮助", "group": "product_help_or_smalltalk", "enabled": true, "display_mode": "text", "allow_knowledge": true, "allow_web": false, "allow_files": false, "allow_chart": false}, {"id": "small_talk", "label": "轻度闲聊", "group": "product_help_or_smalltalk", "enabled": true, "display_mode": "text", "allow_knowledge": false, "allow_web": false, "allow_files": false, "allow_chart": false}], "template_tree": {"router": [{"id": "router.scope", "label": "范围识别", "enabled": true}, {"id": "router.intent", "label": "意图识别", "enabled": true}, {"id": "router.display_mode", "label": "展示模式判定", "enabled": true}, {"id": "router.tool_plan", "label": "工具编排", "enabled": true}], "tool": [{"id": "tool.knowledge.search", "label": "知识检索", "enabled": true}, {"id": "tool.watchlist.detail", "label": "个股详情", "enabled": true}, {"id": "tool.market.index", "label": "指数 / 指标数据", "enabled": true}, {"id": "tool.file.parse", "label": "文件解析", "enabled": true}, {"id": "tool.url.parse", "label": "URL 解析", "enabled": true}, {"id": "tool.web.search", "label": "互联网补充", "enabled": true}, {"id": "tool.chart.render", "label": "图表渲染", "enabled": true}], "answer": [{"id": "answer.qa.structured", "label": "结构化问答", "enabled": true}, {"id": "answer.market.deep", "label": "研究型回答", "enabled": true}, {"id": "answer.report.evidence", "label": "报告 / 证据链回答", "enabled": true}, {"id": "answer.redirect.soft", "label": "温和收口", "enabled": true}], "render": [{"id": "render.text", "label": "文本结果", "enabled": true}, {"id": "render.metric_cards", "label": "指标卡片", "enabled": true}, {"id": "render.chart_kline", "label": "K 线图", "enabled": true}, {"id": "render.chart_line", "label": "线性图", "enabled": true}, {"id": "render.chart_distribution", "label": "分布图", "enabled": true}, {"id": "render.followup_tags", "label": "追问标签", "enabled": true}, {"id": "render.thinking_stream", "label": "思考过程", "enabled": true}]}}, "evidence_chain": {"filter_prompt_system": "你是知识检索相关性过滤助手。你的任务是根据用户问题，从召回候选里剔除明显无关、仅语义相近但业务主题不一致的内容。判断标准必须严格，只有真正能回答问题、或能提供直接支撑信息的知识才能保留。如果问题是具体领域问题，例如 MES、制造、设备、工艺，就不要保留股票、行情、复盘、泛化观点等无关内容。输出必须是 JSON，不要输出任何额外解释。", "filter_prompt_user_template": "用户问题：{query}\n\n候选知识：\n{candidate_blocks}\n\n请返回 JSON，格式如下：\n{\n  \"relevant_ids\": [\"保留的候选ID\"],\n  \"reason\": \"一句话说明筛选结论\"\n}\n如果没有任何相关知识，relevant_ids 返回空数组。", "filter_timeout_seconds": 25, "answer_timeout_seconds": 45}, "review_generation": {"polish_system_prompt": "你是中文投研复盘助手。你的任务是先对大V输入的原始材料做轻量整理和润色，删除明显重复、口语噪音和无效赘述，但必须保留原有事实、判断、风险提示和不确定性。不要新增原文没有出现的观点、数据和投资建议。输出纯文本，按自然段组织，保持便于后续继续组合成完整复盘。", "polish_user_template": "复盘周期：{period_label}\n输入来源：{source_mode}\n作者：{speaker_label}\n触发入口：{entry_point}\n\n请先把下面的原始输入整理成更干净、更适合后续继续生成复盘正文的中间稿。重点保留：市场主线、行业判断、重点个股、验证节点、风险边界。\n\n原始输入：\n{source_text}", "compose_system_prompt": "你是中文投研复盘编辑助手。你要基于大V自己的输入，以及已选中的智能仪表盘卡片，生成一版完整复盘草稿。必须优先保留大V自己的核心判断和风险表达，智能仪表盘只用于补充证据、结构和验证节点。不要编造事实、数字、新闻或结论。输出纯文本，语言专业、克制、可直接给大V继续人工修改。尽量压缩表达，草稿长度默认应少于原始输入长度。", "compose_user_template": "复盘周期：{period_label}\n作者：{speaker_label}\n触发入口：{entry_point}\n纳入样本：{watchlist_text}\n附加标签：{tag_text}\n额外要求：{prompt_text}\n\n这是大V最终确认前的复盘草稿，请基于以下两部分内容生成：\n1. 大V输入/润色稿\n2. 智能仪表盘卡片摘要（每张卡片都附有数据来源和新闻来源）\n3. 大V已选择的知识材料\n\n大V输入：\n{source_text}\n\n智能仪表盘卡片：\n{dashboard_blocks}\n\n知识材料：\n{knowledge_blocks}\n\n请直接输出最终复盘草稿，不要解释处理过程，不要输出“以下是结果”等前缀。", "polish_timeout_seconds": 45, "compose_timeout_seconds": 60}, "l