re: ((sectorMatch || symbolMatch) ? 220 : 0) + (symbolMatch ? 65 : 0) + (majorSignal ? 100 : 0),\n    bucket: (sectorMatch || symbolMatch) ? ''watchlist_sector'' : (majorSignal ? ''major_market'' : ''other''),\n    reason: (sectorMatch || symbolMatch) ? ''命中自选股行业板块或标的'' : (majorSignal ? ''命中社会性重大利好/利空或高影响事件'' : ''其他公开信息''),\n    matched_topics: [\n      ...new Set([\n        ...sectorTokens.filter(tag => [tag, ...(sectorAliases[tag] || [])].some(term => text.includes(term))),\n        ...symbolTokens.filter(tag => text.includes(tag) || compactText.includes(compact(tag))),\n        ...majorKeywords.filter(keyword => text.includes(keyword))\n      ])\n    ]\n  };\n}", "source_prompt": "", "strategy": "watchlist_sector_first", "updated_at": "", "updated_by": "admin", "version": "v3"}}], "feature_flags": {"user_module": true, "kol_module": true, "fundamental_analysis": true, "watchlist": true, "stock_forecast": false, "daily_review": true, "knowledge": true, "community": false, "hermes": true, "channel_module": true, "analytics_module": true, "system_module": true, "vip": false, "dm": true, "fan_interaction": false, "watchlist_fan_comment_interaction": true, "paid_reply": false, "workbench": true, "tenant_portal": false}, "password_gate_enabled": true, "demo_profiles": []}', '2026-08-17 22:46:59') ON CONFLICT ("setting_key") DO UPDATE SET "setting_value" = EXCLUDED."setting_value", "updated_at" = EXCLUDED."updated_at";
